export type TaskStatus = 'todo' | 'in_progress' | 'done';

export class Task {
  constructor(
    readonly id: string,
    readonly projectId: string,
    readonly title: string,
    readonly description: string,
    readonly dueDate: Date | null,
    readonly status: TaskStatus,
    readonly assigneeId: string | null,
  ) {}

  canMarkDone(): boolean {
    return this.status !== 'done';
  }

  withStatus(status: TaskStatus): Task {
    return new Task(
      this.id,
      this.projectId,
      this.title,
      this.description,
      this.dueDate,
      status,
      this.assigneeId,
    );
  }

  withAssignee(assigneeId: string | null): Task {
    return new Task(
      this.id,
      this.projectId,
      this.title,
      this.description,
      this.dueDate,
      this.status,
      assigneeId,
    );
  }
}

=====SOURCE-END=====

